    @JsonProperty("pesoKg")
    private Double pesoKg;

    public ItemPedido() {}

    public ItemPedido(String nome, Double precoUnitario, Integer quantidade, Double pesoKg) {
        this.nome = nome;
        this.precoUnitario = precoUnitario;
        this.quantidade = quantidade;
        this.pesoKg = pesoKg;
    }

    public String getNome() {
        return nome;
    }

