private BigDecimal calcularParcelaComJuros(BigDecimal total, Integer parcelas) {
    BigDecimal taxa = TAXA_JUROS;
    BigDecimal n = BigDecimal.valueOf(parcelas);

    BigDecimal um = BigDecimal.ONE;
    BigDecimal umMaisTaxa = um.add(taxa);

    BigDecimal denominador = um.subtract(
            umMaisTaxa.pow(-parcelas.intValue())
    );

    BigDecimal parcela = total.multiply(taxa).divide(denominador, 10, java.math.RoundingMode.HALF_EVEN);
    return Arredondamento.arredondarParaPar(parcela);
}

